import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as s}from"./chunks/OFF.BrU7kQE-.js";import{_ as o}from"./chunks/M-S-SY8d2.DVL3poO_.js";import{_ as r,o as n,c as l,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const q=JSON.parse('{"title":"Synchronisation xDrip","description":"","frontmatter":{"source_hash":"8ff0f07a91","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/sync.md","filePath":"fr/use/sync.md"}'),c={name:"fr/use/sync.md"};function d(u,t,m,v,h,b){return n(),l("div",null,[...t[0]||(t[0]=[p('<div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_google_circles_communities_grey600_48dp.png" style="width:5%;"> xDrip+ Synchronisation</p></div><div class="warning custom-block"><p class="custom-block-title">Ancienne synchronisation xDrip</p><p>En juillet 2024, Google a arrêté l&#39;<a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">API Firebase</a> obsolète que xDrip utilisait pour la synchronisation xDrip.<br> Mettez à jour xDrip vers une version du <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">23 juillet 2024</a> ou plus récente pour utiliser l&#39;ancienne méthode de synchronisation.<br> Il est recommandé de mettre à jour xDrip vers la dernière version publiée.</p></div><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Les <a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">services Google Play</a> sont indispensables pour utiliser cette fonction. Assurez-vous qu&#39;ils sont présents, activés et non soumis à l&#39;optimisation de la batterie.</p></div><p>xDrip propose un mécanisme unique de synchronisation en temps réel entre appareils Android, qui rend le partage des glycémies et des traitements aussi simple que possible.</p><p>La clé de sécurité sous-jacente peut être personnalisée au lieu d&#39;utiliser la clé du compte Google (non modifiable).</p><div class="admonition xdripitem"><p class="admonition-title">Synchroniser en utilisant la clé de sécurité personnalisé <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Key est utilisé au lieu du compte Google</p></div><h5 id="handset-group-security-sync-key" tabindex="-1">Clé de sécurité de groupe de dispositifs <a class="header-anchor" href="#handset-group-security-sync-key" aria-label="Permalink to &quot;Clé de sécurité de groupe de dispositifs {#handset-group-security-sync-key}&quot;">​</a></h5><p>Une clé unique est créée à l&#39;installation de xDrip (elle sera différente si vous réinstallez xDrip) et doit être la même sur tous les appareils utilisant la synchronisation xDrip. Même si vous pouvez personnaliser cette clé (lettres et chiffres), vous la laisserez généralement telle qu&#39;elle a été générée.</p><div class="admonition xdripitem"><p class="admonition-title">Clé de sécurité de groupe de dispositifs</p><p> Clé de regroupement de synchronisation des appareils</p></div><h5 id="be-master-for-followers" tabindex="-1">Soyez maître pour les Abonnés <a class="header-anchor" href="#be-master-for-followers" aria-label="Permalink to &quot;Soyez maître pour les Abonnés {#be-master-for-followers}&quot;">​</a></h5><p>L&#39;appareil qui reçoit les glycémies du capteur sera le maître, tous les autres seront des abonnés.<br> Un seul maître peut utiliser une même clé de sécurité. Si deux maîtres sont détectés, le dernier arrivé est désactivé et repasse en mode abonné.</p><div class="admonition xdripitem"><p class="admonition-title">Soyez maître pour les Abonnés <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Cet appareil envoie des données aux Abonnés</p></div><h5 id="accept-followers-actions" tabindex="-1">Accepter les actions des Abonnés <a class="header-anchor" href="#accept-followers-actions" aria-label="Permalink to &quot;Accepter les actions des Abonnés {#accept-followers-actions}&quot;">​</a></h5><p>Vous pouvez configurer le téléphone maître pour qu&#39;il reçoive et accepte les traitements et étalonnages des abonnés. Soyez extrêmement prudent avec cette fonction si vous utilisez les étalonnages automatiques. N&#39;oubliez pas non plus que des démarrages et arrêts de capteur peuvent être envoyés par les abonnés et acceptés par le maître.</p><div class="admonition xdripitem"><p class="admonition-title">Accepter les actions des Abonnés <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Les traitements et étalonnages des Abonnés seront acceptés</p></div><h5 id="use-xdrip-cloud" tabindex="-1">Utiliser xDrip Cloud <a class="header-anchor" href="#use-xdrip-cloud" aria-label="Permalink to &quot;Utiliser xDrip Cloud {#use-xdrip-cloud}&quot;">​</a></h5><p>Après l&#39;arrêt par Google, en juillet 2024, de l&#39;<a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">API Firebase</a> obsolète utilisée pour la synchronisation xDrip, une nouvelle méthode de partage a été développée.</p><div class="warning custom-block"><p class="custom-block-title">Doit être réglé de la même façon sur tous les téléphones</p><p>Maître et abonnés. Soit activé pour tous, soit désactivé pour tous.</p></div><div class="admonition xdripitem"><p class="admonition-title">Utiliser xDrip Cloud <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Utilisez les nouveaux serveurs cloud de xDrip+. Les maîtres et les abonnés doivent tous avoir ce paramètre défini à l&#39;identique.</p></div><p>Si xDrip consomme trop de batterie en données mobiles, vous pouvez essayer d&#39;activer cette option.</p><div class="admonition xdripitem"><p class="admonition-title">Économiser l&#39;énergie <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Réduire la charge sur la batterie et le réseau en utilisant le traitement par lots et en excluant les données inutiles</p></div><h5 id="whole-house" tabindex="-1">Maison entière <a class="header-anchor" href="#whole-house" aria-label="Permalink to &quot;Maison entière {#whole-house}&quot;">​</a></h5><p>Basés sur le projet <a href="https://github.com/jamorham/wixel-xDrip" target="_blank" rel="noreferrer">Parakeet</a>, plusieurs appareils <strong>maîtres</strong> peuvent former un réseau couvrant toute la maison.<br> Si vous utilisez des capteurs Libre, vous pouvez aussi utiliser cette fonction : voir <a href="https://github.com/tzachi-dar/LibreAllHouse" target="_blank" rel="noreferrer">ici</a> comment créer votre réseau pour toute la maison.</p><div class="admonition xdripitem"><p class="admonition-title">Maison entière <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Participer au réseau de la maison</p></div><div class="admonition xdripitem"><p class="admonition-title">Mode Libre dans toute la maison <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Ce téléphone sera un collecteur dans tout le réseau domestique</p></div><h5 id="remote-snoozing" tabindex="-1">Mise en veille à distance <a class="header-anchor" href="#remote-snoozing" aria-label="Permalink to &quot;Mise en veille à distance {#remote-snoozing}&quot;">​</a></h5><p>La mise en veille à distance permet de propager la demande de mise en veille dans le groupe. Le maître comme les abonnés peuvent mettre les alarmes en veille. À utiliser avec précaution.</p><div class="admonition xdripitem"><p class="admonition-title">Envoyer la mise en veille vers tous <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> La mise en veille rendra silencieux tous les combinés du groupe avec le paramètre d&#39;acceptation ci-dessous activé sur eux</p></div><div class="admonition xdripitem"><p class="admonition-title">Confirmer l&#39;envoi de mise en veille <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Ouvrir une boîte de dialogue pour confirmer l&#39;envoi de chaque veille distante</p></div><div class="admonition xdripitem"><p class="admonition-title">Accepter les mises en veille distantes <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Autoriser les appareils distants à mettre sous silence les alarmes sur celle-ci</p></div><div class="admonition xdripitem"><p class="admonition-title">Le nom du WiFi doit correspondre <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Accepter uniquement si le nom du réseau WiFi distant commence par les mêmes lettres que les nôtres et correspond très étroitement</p></div><h5 id="local-broadcast" tabindex="-1">Diffusion locale <a class="header-anchor" href="#local-broadcast" aria-label="Permalink to &quot;Diffusion locale {#local-broadcast}&quot;">​</a></h5><p>Diffusion locale envoie ou accepte des mises en veille vers/depuis d&#39;autres applications (non xDrip) installées sur le même téléphone, indépendamment de la mise en veille à distance entre téléphones xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Diffusion locale <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Envoyer des répétitions à d&#39;autres applications sur ce combiné</p></div><div class="admonition xdripitem"><p class="admonition-title">Accepter la diffusion locale <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Accepter les mises en veille d&#39;autres applications sur ce combiné</p></div><h5 id="disable-sync" tabindex="-1">Désactiver la synchronisation <a class="header-anchor" href="#disable-sync" aria-label="Permalink to &quot;Désactiver la synchronisation {#disable-sync}&quot;">​</a></h5><p>Désactiver toutes les fonctionnalités de synchronisation désactive complètement le partage. Vous devrez peut-être redémarrer votre téléphone lorsque vous la réactiverez.</p><p>Vous pouvez utiliser cette option en cas d&#39;échec complet de la synchronisation ou avec un téléphone sans services Google Play.</p><div class="admonition xdripitem"><p class="admonition-title">Désactiver toutes les fonctionnalités de synchronisation <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Palliatif, arrête complètement toute synchronisation. Peut nécessiter le redémarrage après avoir été réactivé. Utiliser avec précaution!</p></div><h3 id="desert-sync" tabindex="-1">Synchronisation milieu désertique <a class="header-anchor" href="#desert-sync" aria-label="Permalink to &quot;Synchronisation milieu désertique {#desert-sync}&quot;">​</a></h3><p>Synchronisation milieu désertique permet la synchronisation xDrip sans internet ni couverture de données mobiles.</p><div class="admonition xdripitem"><p class="admonition-title">Synchronisation milieu désertique</p><p><img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xxhdpi/desert_sync.png" style="width:5%;"> Suivi milieu désert</p></div><p>Synchronisation milieu désertique vous permet de partager les données entre votre xDrip maître et ses abonnés lorsque internet n&#39;est pas disponible. Cela peut arriver en voyage hors couverture réseau ou sur un intranet local (sans accès à internet).</p><p>Activez la synchronisation milieu désertique sur tous les appareils.</p><div class="admonition xdripitem"><p class="admonition-title">Synchronisation milieu désertique <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Activer la fonctionnalité de synchronisation locale sans internet</p></div><p>Si vous connaissez l&#39;adresse IP du maître (cas des intranets locaux), saisissez-la ici.<br> Vous trouverez l&#39;adresse IP du maître dans les paramètres Android du téléphone - À propos du téléphone - Adresse IP.</p><div class="admonition xdripitem"><p class="admonition-title">Adresse IP du maître</p></div><p>Affichez maintenant le QR code des paramètres du maître et scannez-le sur vos abonnés avec <a href="./copysettings.html#auto-configure">Configuration automatique</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher le code QR</p><p>Code-barres à scanner pour les abonnés afin de les configurer automatiquement</p></div><p>Si vous voulez sécuriser votre connexion (intranets locaux et Wi-Fi public), vous pouvez activer https.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser HTTPS <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Ajouter une autre couche de chiffrement pour les réseaux partagés, par exemple pour les Wi-Fi publics</p></div><p>Si vous n&#39;avez ni données mobiles ni Wi-Fi, mettez le téléphone maître en mode point d&#39;accès Wi-Fi et connectez-y les abonnés (partage de connexion). La distance maximale entre les appareils sera limitée. Cela pèsera aussi beaucoup sur la batterie du maître : prévoyez une batterie externe de secours.<br> En partage de connexion, vous devrez activer un <a href="./interapp.html#web-service">service web</a> sur le maître. Assurez-vous que le secret est identique sur le maître et les abonnés.</p><p>Consultez l&#39;état du système pour vérifier que tout se connecte correctement.</p><img src="'+o+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',56)])])}const D=r(c,[["render",d]]);export{q as __pageData,D as default};
